using System.Text.Json.Serialization;
using ThePlaidApi.Core.Models;

namespace ThePlaidApi.Models;

/// <summary>
/// The <c>inflow_model</c> allows you to model a test account that receives regular income or makes regular payments on a loan. Any transactions generated by the <c>inflow_model</c> will appear in addition to randomly generated test data or transactions specified by <c>override_accounts</c>.
/// </summary>
public record InflowModel
{
    /// <summary>
    /// Inflow model. One of the following:
    /// <para>
    /// <c>none</c>: No income
    /// </para>
    /// <para>
    /// <c>monthly-income</c>: Income occurs once per month <c>monthly-balance-payment</c>: Pays off the balance on a liability account at the given statement day of month.
    /// </para>
    /// <para>
    /// <c>monthly-interest-only-payment</c>: Makes an interest-only payment on a liability account at the given statement day of month.
    /// </para>
    /// <para>
    /// Note that account types supported by Liabilities will accrue interest in the Sandbox. The types impacted are account type <c>credit</c> with subtype <c>credit</c> or <c>paypal</c>, and account type <c>loan</c> with subtype <c>student</c> or <c>mortgage</c>.
    /// </para>
    /// </summary>
    [JsonPropertyName("type")]
    public required string Type { get; init; }

    /// <summary>
    /// Amount of income per month. This value is required if <c>type</c> is <c>monthly-income</c>.
    /// </summary>
    [JsonPropertyName("income_amount")]
    public required double IncomeAmount { get; init; }

    /// <summary>
    /// Number between 1 and 28, or <c>last</c> meaning the last day of the month. The day of the month on which the income transaction will appear. This field is required if <c>type</c> is <c>monthly-income</c>, <c>monthly-balance-payment</c> or <c>monthly-interest-only-payment</c>.
    /// </summary>
    [JsonPropertyName("payment_day_of_month")]
    public required double PaymentDayOfMonth { get; init; }

    /// <summary>
    /// The name of the income transaction. This field is required if <c>type</c> is <c>monthly-income</c>, <c>monthly-balance-payment</c> or <c>monthly-interest-only-payment</c>.
    /// </summary>
    [JsonPropertyName("transaction_name")]
    public required string TransactionName { get; init; }

    /// <summary>
    /// Number between 1 and 28, or <c>last</c> meaning the last day of the month. The day of the month on which the balance is calculated for the next payment. This field is required if <c>type</c> is <c>monthly-balance-payment</c> or <c>monthly-interest-only-payment</c>.
    /// </summary>
    [JsonPropertyName("statement_day_of_month")]
    public required string StatementDayOfMonth { get; init; }

    [JsonExtensionData]
    public AdditionalProperties AdditionalProperties { get; init; } = [];
}
